"""Repository hygiene: the example config is generated by setup, and no personal token reaches a tracked file."""
import json
import os
import subprocess
import unittest

from vulnwatch.config import load_config
from vulnwatch.setup import Detected, build_config

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
EXAMPLE = os.path.join(REPO, "config", "config.example.json")
TOKENS = os.path.join(REPO, "config", "private_tokens.txt")


def neutral_config() -> dict:
    d = Detected(user="your-username", language="en", brew="/opt/homebrew/bin/brew",
                 npm_global={"prefix": "~/.npm-global", "node": "/opt/homebrew/bin/node", "npm": "/opt/homebrew/bin/npm"},
                 path_node="/opt/homebrew/bin/node", runtimes=[{"label": "nvm", "path": "~/.nvm/versions/node/*/bin/node",
                                                                "product": "node"}],
                 roots=["~/Code"])
    return build_config(d, "~/vulnwatch", d.roots, "en")


class ExampleConfigTest(unittest.TestCase):
    def test_example_config_matches_build_config(self):
        with open(EXAMPLE, encoding="utf-8") as f:
            self.assertEqual(json.load(f), neutral_config(),
                             "regenerate config/config.example.json from tests.test_hygiene.neutral_config()")

    def test_example_config_loads(self):
        cfg = load_config(EXAMPLE)
        self.assertEqual(cfg.language, "en")
        self.assertFalse(cfg.auto_apply)


class PrivateTokensTest(unittest.TestCase):
    def test_no_private_tokens_in_tracked_files(self):
        if not os.path.isfile(TOKENS):
            self.skipTest("config/private_tokens.txt not present (it is local and git-ignored)")
        with open(TOKENS, encoding="utf-8") as f:
            tokens = [line.strip().lower() for line in f if line.strip() and not line.startswith("#")]
        listed = subprocess.run(["git", "-C", REPO, "ls-files", "-z"], capture_output=True, check=True).stdout
        found = []
        for rel in (p for p in listed.decode("utf-8").split("\0") if p):
            try:
                with open(os.path.join(REPO, rel), encoding="utf-8") as f:
                    text = f.read().lower()
            except (OSError, UnicodeDecodeError):
                continue
            found += ["%s: %s" % (rel, tok) for tok in tokens if tok in text]
        self.assertEqual(found, [])

    def test_tokens_file_is_ignored(self):
        r = subprocess.run(["git", "-C", REPO, "check-ignore", "-q", "config/private_tokens.txt"])
        self.assertEqual(r.returncode, 0, "config/private_tokens.txt must be git-ignored")


if __name__ == "__main__":
    unittest.main()
